   435  static status
   436  Array_encodeBinaryComplex(uintptr_t ptr, size_t length, const UA_DataType *type, Ctx *ctx) {
   437      /* Get the encoding function for the data type. The jumptable at
   438       * UA_BUILTIN_TYPES_COUNT points to the generic UA_encodeBinary method */
   439      size_t encode_index = type->builtin ? type->typeIndex : UA_BUILTIN_TYPES_COUNT;
   440      encodeBinarySignature encodeType = encodeBinaryJumpTable[encode_index];
   441
   442      /* Encode every element */
   443      for(size_t i = 0; i < length; ++i) {
   444          u8 *oldpos = ctx->pos;
   445          status ret = encodeType((const void*)ptr, type, ctx);
   446          ptr += type->memSize;
   447          /* Encoding failed, switch to the next chunk when possible */
   448          if(ret != UA_STATUSCODE_GOOD) {
   449              if(ret == UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED) {
   450                  ctx->pos = oldpos; /* Set buffer position to the end of the last encoded element */
   451                  ret = exchangeBuffer(ctx);
   452                  ptr -= type->memSize; /* Undo to retry encoding the ith element */
   453                  --i;
   454              }
   455              UA_assert(ret != UA_STATUSCODE_BADENCODINGLIMITSEXCEEDED);
   456              if(ret != UA_STATUSCODE_GOOD)
   457                  return ret; /* Unrecoverable fail */
   458          }
   459      }
   460      return UA_STATUSCODE_GOOD;
   461  }
